def main():
    spec = {"wave": "mori-r50-a2w1", "reportDir": ".ufo/waves/round-50/a2w1", "context": context, "items": items}
    with open(os.path.join(W, "a2w1-spec.json"), "w") as f:
        json.dump(spec, f, indent=1)
    roles = {}
    for it in items:
        roles[it["role"]] = roles.get(it["role"], 0) + 1
    flash = sum(v for k, v in roles.items() if k in ("executor", "scribe", "critic", "sentinel", "simplifier", "revenger"))
    attack = sum(v for k, v in roles.items() if k in ("reviewer", "critic", "mutation-tester"))
    print(len(items), roles, "flash=%d attack=%d" % (flash, attack))


if __name__ == "__main__":
    main()
